#pragma once#undef CLIENTDLL_API#ifdef QUEUEAPM_EXPORTS#define CLIENTDLL_API __declspec(dllexport)#else#define CLIENTDLL_API __declspec(dllimport)#endifstruct CLIENTDLL_API INetworkTransport{  virtual bool IsConnected() = 0;  virtual bool CreateTransport( LPCSTR pszServer, LPCSTR pszPointName, USHORT port ) = 0;  virtual bool CloseTransport() = 0;  virtual bool ReadData( UINT dwSize, LPVOID pReply, LPDWORD lpNumberOfBytesRead ) = 0;  virtual bool WriteData(LPVOID req, UINT dwReqSize, LPDWORD lpNumberOfBytesWritten ) = 0;};